<template><main class="container reading page-section"><div v-if="loading" class="empty">正在载入文章…</div><div v-else-if="error" class="empty"><h1>{{error}}</h1><RouterLink class="button" to="/login">登录</RouterLink></div><article v-else-if="post"><p class="eyebrow">{{post.categories?.map((c:any)=>c.name).join(' · ')}}</p><h1 class="page-title">{{post.title}}</h1><div class="byline"><RouterLink :to="`/u/${post.blog_slug}`">{{post.username}}</RouterLink><span>{{date(post.published_at)}}</span><span>{{post.reading_minutes}} 分钟阅读</span></div><img v-if="post.cover_image" class="cover" :src="post.cover_image" alt="文章封面"><p v-if="post.excerpt" class="lead">{{post.excerpt}}</p><div class="article" v-html="html"></div><div class="article-actions"><button class="button" @click="like"><AppIcon name="heart" :size="17"/> {{post.like_count}}</button><button class="button" @click="bookmark"><AppIcon name="bookmark" :size="17"/> 收藏</button><button class="button button-ghost" @click="report">举报</button></div><section class="comments"><h2>评论</h2><form v-if="loggedIn&&canComment" @submit.prevent="comment"><textarea v-model="commentText" aria-label="写评论" placeholder="写下你的想法…"></textarea><button class="button button-primary">发表评论</button></form><p v-else-if="canComment" class="muted">登录后参与讨论。</p><div v-for="comment in comments" :key="comment.id" class="comment"><b>{{comment.username}}</b><span class="muted"> · {{date(comment.created_at)}}</span><p>{{comment.content}}</p><button v-if="loggedIn&&!comment.parent_id" class="reply" @click="replyTo=comment.id">回复</button><button v-if="comment.author_id===currentUserId" class="reply delete" @click="removeComment(comment.id)">删除</button><form v-if="replyTo===comment.id" @submit.prevent="comment"><textarea v-model="commentText" aria-label="回复评论" placeholder="回复这条评论"></textarea><button class="button">发送回复</button></form></div></section></article></main></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,RouterLink}from'vue-router';import{marked}from'marked';import DOMPurify from'dompurify';import http from'@/services/http';import AppIcon from'@/components/AppIcon.vue';const route=useRoute(),post=ref<any>(),comments=ref<any[]>([]),loading=ref(true),error=ref(''),commentText=ref(''),replyTo=ref<number|null>(null),canComment=ref(false),loggedIn=localStorage.getItem('isLoggedIn')==='true',currentUserId=Number(JSON.parse(localStorage.getItem('userInfo')||'{}').id);const html=computed(()=>DOMPurify.sanitize(String(marked.parse(post.value?.content_markdown||''))));const date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));const shareConfig=()=>route.query.share?{params:{share:String(route.query.share)}}:{};async function load(){try{const r=await http.get(`/api/public/posts/${route.params.slug}`,shareConfig());post.value=r.data.post;canComment.value=r.data.canComment;comments.value=(await http.get(`/api/posts/${post.value.id}/comments`,shareConfig())).data.items}catch(e:any){error.value=e.response?.data?.error?.message||'文章不可用'}finally{loading.value=false}}async function like(){if(!loggedIn)return location.assign('/login');await http.post(`/api/posts/${post.value.id}/like`,{},shareConfig());post.value.like_count++}async function bookmark(){if(!loggedIn)return location.assign('/login');await http.post(`/api/posts/${post.value.id}/bookmark`,{},shareConfig())}async function comment(){if(!commentText.value.trim())return;await http.post(`/api/posts/${post.value.id}/comments`,{content:commentText.value,parentId:replyTo.value},shareConfig());commentText.value='';replyTo.value=null;comments.value=(await http.get(`/api/posts/${post.value.id}/comments`,shareConfig())).data.items}async function removeComment(id:number){if(!confirm('确定删除这条评论？'))return;await http.delete(`/api/comments/${id}`);await load()}async function report(){if(!loggedIn)return location.assign('/login');await http.post('/api/reports',{postId:post.value.id,reason:'其他'},shareConfig());alert('举报已提交')}onMounted(load)</script>
<style scoped>.reading{max-width:820px}.page-title{font-size:clamp(2.1rem,6vw,3.5rem);line-height:1.16}.byline{display:flex;gap:10px;flex-wrap:wrap;color:var(--muted);font-size:.92rem}.byline a{color:var(--accent);font-weight:700}.cover{width:100%;max-height:440px;object-fit:cover;border-radius:var(--radius);margin:28px 0}.lead{font-size:1.18rem;color:var(--muted);border-left:3px solid var(--accent);padding-left:16px}.article{font-size:1.05rem;line-height:1.85}.article :deep(img){max-width:100%;height:auto}.article :deep(pre){overflow:auto;padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:8px}.article :deep(blockquote){margin-left:0;padding-left:16px;border-left:3px solid var(--border);color:var(--muted)}.article-actions{display:flex;gap:8px;border-top:1px solid var(--border);padding-top:20px;margin-top:36px}.comments{margin-top:50px}.comments textarea{width:100%;min-height:90px;margin-bottom:8px;padding:10px;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:8px}.comment{padding:16px 0;border-bottom:1px solid var(--border)}.comment p{white-space:pre-wrap}.reply{border:0;padding:0;background:transparent;color:var(--accent)}</style>
